static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // 假设 groups=1, stride=1, padding=0, dilation=1, output_padding=0
    auto xShape = context->GetInputShape(0)->GetOriginShape();
    auto wShape = context->GetInputShape(1)->GetOriginShape();

    uint32_t n = static_cast<uint32_t>(xShape.GetDim(0));
    uint32_t cin = static_cast<uint32_t>(xShape.GetDim(1));
    uint32_t lin = static_cast<uint32_t>(xShape.GetDim(2));
    uint32_t w_cin = static_cast<uint32_t>(wShape.GetDim(0));
    uint32_t cout = static_cast<uint32_t>(wShape.GetDim(1));
    uint32_t kernel = static_cast<uint32_t>(wShape.GetDim(2));

    // 简化: groups=1 情况下 w_cin 应与 cin 一致
    (void)w_cin;

    uint32_t lout = lin + kernel - 1;

    const uint32_t maxBlocks = 32; // 可根据平台与任务规模调整
    uint32_t blockDim = std::min<uint32_t>(n * cout, maxBlocks);
    context->SetBlockDim(blockDim);

    ConvTransposed1dCustomTilingData tiling;
    tiling.set_n(n);
    tiling.set_cin(cin);
    tiling.set_cout(cout);
    tiling.set_lin(lin);
    tiling.set_kernel(kernel);
    tiling.set_lout(lout);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

